{
  "interpretation": {
    "name": "TightenCheckRecordAndReturnNR7OnLine1",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring NR7 to station st1, tighten the fasteners of variant F25 with the MES program, evaluate and record the result, then return NR7 to the crib and release the reservation.",
    "constraints": [
      "NR7 must be reserved for line 1 before any use and released at the end",
      "NR7 must be at st1 (transport-tool to station completed) before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program; no numeric process values in the Recipe",
      "The tightening must be evaluated against its program and recorded for traceability",
      "transport-tool must be delegated to agvexecutor",
      "NR7 must be back in the crib before the reservation is released"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-off, execute now",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tighten-evaluate-record-return",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-f25",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "Assess",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-program-f25", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Assess",
        "next": "Return",
        "steps": [
          {
            "name": "evaluate-nr7-tightening",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-program-f25"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-nr7-tightening",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Return",
        "next": null,
        "steps": [
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
